import{_ as i,o,c as l,a2 as a}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"7.3 变压器的运行与维护","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-3-bian-ya-qi-de-yun-xing-yu-wei-hu.md","filePath":"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-3-bian-ya-qi-de-yun-xing-yu-wei-hu.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/07-chapter-7-bian-ya-qi/7-3-bian-ya-qi-de-yun-xing-yu-wei-hu.md"};function n(e,t,s,d,u,g){return o(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="_7-3-变压器的运行与维护" tabindex="-1">7.3 变压器的运行与维护 <a class="header-anchor" href="#_7-3-变压器的运行与维护" aria-label="Permalink to &quot;7.3 变压器的运行与维护&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>变压器长期带电运行,要&quot;看着它、养着它&quot;。这一节讲运行中监视什么、哪些是异常信号,以及维护时的安全要点。</p><h2 id="一、运行中要监视什么" tabindex="-1">一、运行中要监视什么 <a class="header-anchor" href="#一、运行中要监视什么" aria-label="Permalink to &quot;一、运行中要监视什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>监视项目</th><th>正常情况</th><th>异常信号</th></tr></thead><tbody><tr><td><strong>温度</strong></td><td>上层油温不超过规定值(一般 ≤ 85 ℃ 左右)</td><td>温度过高、急剧上升</td></tr><tr><td><strong>声音</strong></td><td>平稳的&quot;嗡嗡&quot;声</td><td>异响、爆裂声、放电声</td></tr><tr><td><strong>电压/电流</strong></td><td>电压平稳、负荷不超</td><td>电压波动大、长期过载</td></tr><tr><td><strong>油位/渗油</strong></td><td>油位正常、无渗漏</td><td>油位过低、渗油</td></tr><tr><td><strong>绝缘</strong></td><td>绝缘良好</td><td>绝缘电阻下降</td></tr></tbody></table><blockquote><p>💡 变压器有&quot;嗡嗡&quot;声是<strong>正常的</strong>(交变磁通使铁芯轻微振动),但<strong>声音变大、出现异响</strong>就是异常。</p></blockquote><h2 id="二、常见异常现象与判断" tabindex="-1">二、常见异常现象与判断 <a class="header-anchor" href="#二、常见异常现象与判断" aria-label="Permalink to &quot;二、常见异常现象与判断&quot;">​</a></h2><ul><li><strong>温度过高</strong>:过载、散热不良、油位低、内部故障;</li><li><strong>异响/放电声</strong>:绕组松动、绝缘击穿(内部放电);</li><li><strong>渗油</strong>:密封老化,油位下降,影响散热和绝缘;</li><li><strong>电压异常</strong>:输入电压过高或过低、系统故障;</li><li><strong>气味</strong>:有烧焦味说明绝缘过热或烧损。</li></ul><blockquote><p>⚠️ 发现异常应立即<strong>减载或停用变压器</strong>,检查处理后再投运——&quot;带病运行&quot;可能烧毁设备引发事故。</p></blockquote><h2 id="三、维护与检修的安全要点" tabindex="-1">三、维护与检修的安全要点 <a class="header-anchor" href="#三、维护与检修的安全要点" aria-label="Permalink to &quot;三、维护与检修的安全要点&quot;">​</a></h2><ol><li><strong>停用检修前</strong>: <ul><li>断开电源,并<strong>验电</strong>;</li><li>对绕组、电缆等<strong>放电</strong>(变压器绕组有残余电荷),防止触电;</li><li>挂&quot;禁止合闸,有人工作!&quot;标示牌;</li></ul></li><li><strong>定期检查</strong>: <ul><li>检查绝缘电阻(用兆欧表,变压器停电后测量);</li><li>检查绝缘油油位、颜色(油质劣化要处理);</li><li>检查接线端子是否发热、松动;</li></ul></li><li><strong>环境要求</strong>:变压器房(箱)要<strong>通风、防潮、防尘</strong>,附近无易燃物。</li></ol><h2 id="四、考点提示" tabindex="-1">四、考点提示 <a class="header-anchor" href="#四、考点提示" aria-label="Permalink to &quot;四、考点提示&quot;">​</a></h2><ul><li>✅ 上层油温一般不超过 <strong>85 ℃</strong> 左右。</li><li>✅ 变压器正常有&quot;嗡嗡&quot;声;异响、放电声是异常。</li><li>✅ 检修前:断开电源 → 验电 → <strong>放电</strong> → 挂标示牌。</li><li>✅ 变压器房要通风防潮防尘。</li><li>⚠️ 易混点:正常嗡嗡声 vs 异常异响,判断题常考&quot;变压器运行时无声无息才对&quot;→ 错误。</li></ul><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><ul><li>运行监视:温度、声音、电压电流、油位、绝缘。</li><li>异常要停用处理,不&quot;带病运行&quot;。</li><li>检修前停电、验电、放电、挂牌,确保安全。</li></ul><h2 id="六、自测练习" tabindex="-1">六、自测练习 <a class="header-anchor" href="#六、自测练习" aria-label="Permalink to &quot;六、自测练习&quot;">​</a></h2><ol><li>(判断)变压器正常运行时,会发出轻微的&quot;嗡嗡&quot;声。( )</li><li>(单选)油浸式变压器运行中,上层油温一般不应超过()。 A. 60 ℃　B. 85 ℃　C. 100 ℃　D. 120 ℃</li><li>(判断)变压器出现异响、放电声,应继续带病运行观察。( )</li><li>(判断)变压器检修前,应对绕组进行放电处理。( )</li><li>(判断)变压器房(箱)应保持通风、防潮、防尘。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。铁芯轻微振动产生正常&quot;嗡嗡&quot;声。</li><li><strong>B</strong>。上层油温一般不超过 85 ℃ 左右。</li><li><strong>×</strong>。发现异常应立即停用检查,不能带病运行。</li><li><strong>√</strong>。停电后对绕组放电,防止残余电荷触电。</li><li><strong>√</strong>。通风防潮防尘是变压器室的基本要求。</li></ol></details>',18)])])}const q=i(r,[["render",n]]);export{c as __pageData,q as default};
